  expect(splitEvidence('x.md#A, y.md#B')).toEqual(['x.md#A','y.md#B']);
  expect(splitEvidence('AGENTS.md#Results, caveats')).toEqual(['AGENTS.md#Results, caveats']);
  expect(splitEvidence('one.ts#L1')).toEqual(['one.ts#L1']);
 });
